#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <math.h>

typedef struct {
    int *heap;      // array of indices into nums
    int size;
    int capacity;
    int (*cmp)(int a, int b, int *nums);
    int *nums;
} Heap;

static int cmpMax(int a, int b, int *nums) {
    // max heap: larger nums[a] first, if tie smaller index first
    if (nums[a] != nums[b]) return nums[b] - nums[a];
    return a - b;
}

static int cmpMin(int a, int b, int *nums) {
    // min heap: smaller nums[a] first, if tie smaller index first
    if (nums[a] != nums[b]) return nums[a] - nums[b];
    return a - b;
}

Heap *heapCreate(int capacity, int (*cmp)(int,int,int*), int *nums) {
    Heap *h = (Heap*)malloc(sizeof(Heap));
    h->heap = (int*)malloc(sizeof(int)*capacity);
    h->size = 0;
    h->capacity = capacity;
    h->cmp = cmp;
    h->nums = nums;
    return h;
}

void heapFree(Heap *h) {
    free(h->heap);
    free(h);
}

void heapSwap(Heap *h, int i, int j) {
    int tmp = h->heap[i];
    h->heap[i] = h->heap[j];
    h->heap[j] = tmp;
}

void heapSiftUp(Heap *h, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (h->cmp(h->heap[idx], h->heap[parent], h->nums) > 0) {
            heapSwap(h, idx, parent);
            idx = parent;
        } else {
            break;
        }
    }
}

void heapSiftDown(Heap *h, int idx) {
    int size = h->size;
    while (1) {
        int left = idx * 2 + 1;
        int right = idx * 2 + 2;
        int largest = idx;
        if (left < size && h->cmp(h->heap[left], h->heap[largest], h->nums) > 0) {
            largest = left;
        }
        if (right < size && h->cmp(h->heap[right], h->heap[largest], h->nums) > 0) {
            largest = right;
        }
        if (largest != idx) {
            heapSwap(h, idx, largest);
            idx = largest;
        } else {
            break;
        }
    }
}

void heapPush(Heap *h, int val) {
    if (h->size == h->capacity) {
        h->capacity = h->capacity * 2;
        h->heap = (int*)realloc(h->heap, sizeof(int)*h->capacity);
    }
    h->heap[h->size++] = val;
    heapSiftUp(h, h->size - 1);
}

// Lazy removal: we will mark elements to remove in a hash map (or array) and remove them when they appear on top
// But since nums length can be up to 1e5, we can use an array for counts of removals

typedef struct {
    int *heap;
    int size;
    int capacity;
    int (*cmp)(int a, int b, int *nums);
    int *nums;
    int *delCount; // count of how many times an index is marked for deletion
} LazyHeap;

LazyHeap *lazyHeapCreate(int capacity, int (*cmp)(int,int,int*), int *nums, int n) {
    LazyHeap *h = (LazyHeap*)malloc(sizeof(LazyHeap));
    h->heap = (int*)malloc(sizeof(int)*capacity);
    h->size = 0;
    h->capacity = capacity;
    h->cmp = cmp;
    h->nums = nums;
    h->delCount = (int*)calloc(n, sizeof(int));
    return h;
}

void lazyHeapFree(LazyHeap *h) {
    free(h->heap);
    free(h->delCount);
    free(h);
}

void lazyHeapSwap(LazyHeap *h, int i, int j) {
    int tmp = h->heap[i];
    h->heap[i] = h->heap[j];
    h->heap[j] = tmp;
}

void lazyHeapSiftUp(LazyHeap *h, int idx) {
    while (idx > 0) {
        int parent = (idx - 1) / 2;
        if (h->cmp(h->heap[idx], h->heap[parent], h->nums) > 0) {
            lazyHeapSwap(h, idx, parent);
            idx = parent;
        } else {
            break;
        }
    }
}

void lazyHeapSiftDown(LazyHeap *h, int idx) {
    int size = h->size;
    while (1) {
        int left = idx * 2 + 1;
        int right = idx * 2 + 2;
        int largest = idx;
        if (left < size && h->cmp(h->heap[left], h->heap[largest], h->nums) > 0) {
            largest = left;
        }
        if (right < size && h->cmp(h->heap[right], h->heap[largest], h->nums) > 0) {
            largest = right;
        }
        if (largest != idx) {
            lazyHeapSwap(h, idx, largest);
            idx = largest;
        } else {
            break;
        }
    }
}

void lazyHeapPush(LazyHeap *h, int val) {
    if (h->size == h->capacity) {
        h->capacity = h->capacity * 2;
        h->heap = (int*)realloc(h->heap, sizeof(int)*h->capacity);
    }
    h->heap[h->size++] = val;
    lazyHeapSiftUp(h, h->size - 1);
}

void lazyHeapRemoveTop(LazyHeap *h) {
    if (h->size == 0) return;
    h->heap[0] = h->heap[h->size - 1];
    h->size--;
    lazyHeapSiftDown(h, 0);
}

int lazyHeapTop(LazyHeap *h) {
    if (h->size == 0) return -1;
    return h->heap[0];
}

// Remove elements marked for deletion from top
void lazyHeapPrune(LazyHeap *h) {
    while (h->size > 0) {
        int top = lazyHeapTop(h);
        if (h->delCount[top] > 0) {
            h->delCount[top]--;
            lazyHeapRemoveTop(h);
        } else {
            break;
        }
    }
}

void lazyHeapErase(LazyHeap *h, int val) {
    h->delCount[val]++;
    // We do not remove immediately, lazy removal
}

// Balance heaps so that maxHeap size == minHeap size or maxHeap size == minHeap size + 1
void balanceHeaps(LazyHeap *maxHeap, LazyHeap *minHeap) {
    if (maxHeap->size > minHeap->size + 1) {
        // Move top from maxHeap to minHeap
        lazyHeapPrune(maxHeap);
        int top = lazyHeapTop(maxHeap);
        lazyHeapRemoveTop(maxHeap);
        lazyHeapPush(minHeap, top);
    } else if (maxHeap->size < minHeap->size) {
        // Move top from minHeap to maxHeap
        lazyHeapPrune(minHeap);
        int top = lazyHeapTop(minHeap);
        lazyHeapRemoveTop(minHeap);
        lazyHeapPush(maxHeap, top);
    }
    lazyHeapPrune(maxHeap);
    lazyHeapPrune(minHeap);
}

double getMedian(LazyHeap *maxHeap, LazyHeap *minHeap, int k, int *nums) {
    lazyHeapPrune(maxHeap);
    lazyHeapPrune(minHeap);
    if (k % 2 == 1) {
        int top = lazyHeapTop(maxHeap);
        return (double)nums[top];
    } else {
        int top1 = lazyHeapTop(maxHeap);
        int top2 = lazyHeapTop(minHeap);
        return ((double)nums[top1] + (double)nums[top2]) / 2.0;
    }
}

double* medianSlidingWindow(int* nums, int numsSize, int k, int* returnSize){
    if (numsSize == 0 || k == 0) {
        *returnSize = 0;
        return NULL;
    }
    int n = numsSize;
    int outSize = n - k + 1;
    double *res = (double*)malloc(sizeof(double)*outSize);

    // maxHeap: store smaller half, max heap by nums value
    // minHeap: store larger half, min heap by nums value
    LazyHeap *maxHeap = lazyHeapCreate(k, cmpMax, nums, n);
    LazyHeap *minHeap = lazyHeapCreate(k, cmpMin, nums, n);

    for (int i = 0; i < k; i++) {
        lazyHeapPush(maxHeap, i);
    }
    // Move half from maxHeap to minHeap to balance
    for (int i = 0; i < k/2; i++) {
        lazyHeapPrune(maxHeap);
        int top = lazyHeapTop(maxHeap);
        lazyHeapRemoveTop(maxHeap);
        lazyHeapPush(minHeap, top);
    }

    res[0] = getMedian(maxHeap, minHeap, k, nums);

    for (int i = k; i < n; i++) {
        int out_idx = i - k;
        int in_idx = i;

        // Remove out_idx
        if (nums[out_idx] <= nums[lazyHeapTop(maxHeap)]) {
            lazyHeapErase(maxHeap, out_idx);
        } else {
            lazyHeapErase(minHeap, out_idx);
        }

        // Add in_idx
        if (nums[in_idx] <= nums[lazyHeapTop(maxHeap)]) {
            lazyHeapPush(maxHeap, in_idx);
        } else {
            lazyHeapPush(minHeap, in_idx);
        }

        balanceHeaps(maxHeap, minHeap);

        res[out_idx + 1] = getMedian(maxHeap, minHeap, k, nums);
    }

    lazyHeapFree(maxHeap);
    lazyHeapFree(minHeap);

    *returnSize = outSize;
    return res;
}

